package com.example.lifecoach

import android.app.*;import android.content.*;import androidx.activity.result.contract.ActivityResultContracts;import android.os.*;import androidx.activity.*;import androidx.activity.compose.*;import androidx.compose.foundation.*;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.foundation.shape.RoundedCornerShape;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.*;import androidx.compose.ui.graphics.Color;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.lifecycle.*;import androidx.lifecycle.viewmodel.compose.viewModel;import com.example.lifecoach.ai.DeepSeekClient;import com.example.lifecoach.data.*;import com.example.lifecoach.worker.*;import kotlinx.coroutines.*;import kotlinx.coroutines.flow.*;import java.text.SimpleDateFormat;import java.util.*

class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);if(Build.VERSION.SDK_INT>=33)requestPermissions(arrayOf("android.permission.POST_NOTIFICATIONS"),99);setContent{MaterialTheme(colorScheme=darkColorScheme(primary=Color(0xff8fa8bf),surface=Color(0xff182028),background=Color(0xff10161c))){CoachApp()}};MainScope().launch{CoachRepository(this@MainActivity).recordWake()};KeepAliveService.start(this);AlarmScheduler.scheduleNext(this);androidx.work.WorkManager.getInstance(this).enqueueUniquePeriodicWork("catchup",androidx.work.ExistingPeriodicWorkPolicy.UPDATE,androidx.work.PeriodicWorkRequestBuilder<CatchUpWorker>(30,java.util.concurrent.TimeUnit.MINUTES).build())}}
class MainVM(app:Application):AndroidViewModel(app){val repo=CoachRepository(app);val ai=DeepSeekClient(repo);var tab by mutableIntStateOf(0);var pending by mutableStateOf<List<PendingPrompt>>(emptyList());var tasks by mutableStateOf<List<Task>>(emptyList());var records by mutableStateOf<List<DailyRecord>>(emptyList());var key by mutableStateOf(repo.apiKey());var chat by mutableStateOf<List<ChatMessage>>(emptyList());init{refresh();viewModelScope.launch{repo.chat().collect{chat=it}}};fun refresh(){viewModelScope.launch{repo.carryOver();repo.catchUp();pending=repo.pending();tasks=repo.tasks();records=repo.recentRecords()}};fun answer(p:PendingPrompt,a:String?,skip:Boolean=false){viewModelScope.launch{repo.answer(p,a,skip);refresh()}};fun toggle(t:Task){viewModelScope.launch{repo.toggleTask(t);refresh()}};fun add(t:String){viewModelScope.launch{repo.addTask(t);refresh()}};fun roll(t:Task){viewModelScope.launch{repo.rollTask(t);refresh()}};fun send(s:String){if(s.isBlank())return;viewModelScope.launch{repo.addChat(ChatMessage(timestamp=System.currentTimeMillis(),role="user",content=s));val ctx="今天 ${today()}，抽烟 ${records.firstOrNull()?.cigarettes?:0} 支，学习 ${records.firstOrNull()?.studyMinutes?:0} 分钟。";val out=withContext(Dispatchers.IO){ai.ask(s,ctx)};repo.addChat(ChatMessage(timestamp=System.currentTimeMillis(),role="assistant",content=out))}};fun exportJson(ctx:android.content.Context){viewModelScope.launch{val out=repo.exportJson();val i=android.content.Intent(android.content.Intent.ACTION_SEND).apply{type="application/json";putExtra(android.content.Intent.EXTRA_TEXT,out)};ctx.startActivity(android.content.Intent.createChooser(i,"导出数据"))}}}
@Composable fun CoachApp(vm:MainVM=viewModel()) {Scaffold(bottomBar={NavigationBar{listOf("今天","教练","数据","设置").forEachIndexed{idx,t->NavigationBarItem(selected=vm.tab==idx,onClick={vm.tab=idx},icon={Text(listOf("●","✦","▥","⚙")[idx])},label={Text(t)})}}}){p->Box(Modifier.padding(p)){when(vm.tab){0->Today(vm);1->Chat(vm);2->Data(vm);3->Settings(vm)}}}}
@Composable fun Today(vm:MainVM){var newTask by remember{mutableStateOf("")};LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("今天",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Text("问题在这里等你。答完就消失。",color=Color.LightGray)};if(vm.pending.isNotEmpty()){item{Text("待回答 · ${vm.pending.size}",style=MaterialTheme.typography.titleMedium)};items(vm.pending.take(3),key={it.id}){PromptCard(it,vm)}};item{Text("三件事 · ${vm.tasks.count{it.done}}/${vm.tasks.size.coerceAtMost(3)}",style=MaterialTheme.typography.titleMedium)};items(vm.tasks,key={it.id}){t->TaskRow(t,{vm.toggle(t)},{vm.roll(t)})};if(vm.tasks.size<3)item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp),verticalAlignment=Alignment.CenterVertically){OutlinedTextField(newTask,{newTask=it},Modifier.weight(1f),singleLine=true,placeholder={Text("加一件今天要做的事")});Button(onClick={if(newTask.isNotBlank()){vm.add(newTask);newTask=""}}){Text("加入")}}};if(vm.pending.isEmpty())item{Card{Text("今天暂时没有待回答的问题。到点会出现；如果错过，重新打开也会补回来。",Modifier.padding(18.dp))}}}}
@Composable fun PromptCard(p:PendingPrompt,vm:MainVM){var text by remember(p.id){mutableStateOf("")};Card(shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){if(p.isCatchUp)Text("补发 · ${SimpleDateFormat("HH:mm",Locale.getDefault()).format(Date(p.scheduledTime))}",color=Color.Gray);Text(p.question,style=MaterialTheme.typography.titleLarge);val opts=try{com.google.gson.Gson().fromJson(p.optionsJson?:"[]",Array<String>::class.java).toList()}catch(_:Exception){emptyList()};when(p.type){"TEXT"->{OutlinedTextField(text,{text=it},Modifier.fillMaxWidth(),singleLine=true,placeholder={Text("写一句")})};else->{Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(8.dp)){opts.forEach{o->Button(onClick={vm.answer(p,o)}){Text(o)}}}}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.End){TextButton(onClick={vm.answer(p,null,true)}){Text("跳过")};if(p.type=="TEXT")Button(onClick={vm.answer(p,text)}){Text("回答")}}}}}
@Composable fun TaskRow(t:Task,onToggle:()->Unit,onRoll:()->Unit){Row(Modifier.fillMaxWidth().clickable{onToggle()}.padding(vertical=8.dp),verticalAlignment=Alignment.CenterVertically){Text(if(t.done)"☑" else "□",style=MaterialTheme.typography.headlineSmall);Spacer(Modifier.width(12.dp));Text(t.title,modifier=Modifier.weight(1f),color=if(t.rollCount>=3)Color(0xffff8a80) else Color.Unspecified);if(t.rollCount>0)Text("顺延×${t.rollCount}",color=Color.Gray);TextButton(onClick=onRoll){Text("顺延")}}}
@Composable fun Chat(vm:MainVM){var input by remember{mutableStateOf("")};Column(Modifier.fillMaxSize().padding(16.dp)){Text("教练",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Text("不想打字就点快捷问句。",color=Color.Gray);Row(Modifier.padding(vertical=12.dp),horizontalArrangement=Arrangement.spacedBy(6.dp)){listOf("我现在不想干","今天怎么排","我又滑了","复盘今天").forEach{s->AssistChip(onClick={vm.send(s)},label={Text(s)})}};LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp)){items(vm.chat,key={it.id}){m->Surface(shape=RoundedCornerShape(14.dp),color=if(m.role=="user")Color(0xff294154) else Color(0xff232d36),modifier=Modifier.fillMaxWidth()){Text(m.content,Modifier.padding(14.dp))}}};Row(horizontalArrangement=Arrangement.spacedBy(8.dp),verticalAlignment=Alignment.CenterVertically){OutlinedTextField(input,{input=it},Modifier.weight(1f),singleLine=true,placeholder={Text("说一句")});Button(onClick={vm.send(input);input=""}){Text("发送")}}}}
@Composable fun Data(vm:MainVM){val rs=vm.records;LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("数据",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold)};item{MetricCard("抽烟",rs.map{it.cigarettes},"支/天")};item{StreakCard("出门走路",rs.count{it.walked},rs.size)};item{MetricCard("完成率",rs.map{it.completionRate},"%")};item{SleepCard(rs)};item{Card{Column(Modifier.padding(16.dp)){Text("周报 / 月报",style=MaterialTheme.typography.titleMedium);Text(if(rs.isEmpty())"积累几天数据后，这里会出现基于事实的总结。" else "近 ${rs.size} 天已有 ${rs.count{it.walked}} 天出门走路。",color=Color.Gray)}}}}}
@Composable fun MetricCard(title:String,values:List<Int>,unit:String){Card{Column(Modifier.padding(16.dp)){Text(title,style=MaterialTheme.typography.titleMedium);Text("${values.firstOrNull()?:0} $unit",style=MaterialTheme.typography.headlineSmall);if(values.isNotEmpty()){Row(Modifier.fillMaxWidth().height(70.dp),horizontalArrangement=Arrangement.spacedBy(3.dp),verticalAlignment=Alignment.Bottom){values.take(30).reversed().forEach{v->Box(Modifier.width(7.dp).height((v.coerceAtLeast(2)*3).dp).background(Color(0xff8fa8bf),RoundedCornerShape(3.dp)))}}}}}}
@Composable fun StreakCard(title:String,done:Int,total:Int){Card{Column(Modifier.padding(16.dp)){Text(title,style=MaterialTheme.typography.titleMedium);Text("${done} 天 / ${total.coerceAtLeast(1)} 天",style=MaterialTheme.typography.headlineSmall);Text("连续记录从每日数据计算，不靠额外打卡。",color=Color.Gray)}}}
@Composable fun SleepCard(rs:List<DailyRecord>){Card{Column(Modifier.padding(16.dp)){Text("睡眠 × 精神",style=MaterialTheme.typography.titleMedium);Text("${rs.count{it.sleepTime!=null&&it.clarity!=null}} 个有效点",style=MaterialTheme.typography.headlineSmall);Text("记录睡觉时间和次日精神后，这里会显示关系。",color=Color.Gray)}}}
@Composable fun Settings(vm:MainVM){val ctx=androidx.compose.ui.platform.LocalContext.current;val picker=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){u->if(u!=null)vm.viewModelScope.launch{ctx.contentResolver.openInputStream(u)?.bufferedReader()?.use{vm.repo.importJson(it.readText())};vm.refresh()}};var key by remember{mutableStateOf(vm.key)};var msg by remember{mutableStateOf("")};LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("设置",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold)};item{Card{Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("DeepSeek API Key",style=MaterialTheme.typography.titleMedium);OutlinedTextField(key,{key=it},Modifier.fillMaxWidth(),singleLine=true);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick={vm.repo.setApiKey(key);vm.key=key;msg="已保存。"}){Text("保存")};OutlinedButton(onClick={vm.send("测试连接：只回复已连接")}){Text("测试连接")}};if(msg.isNotBlank())Text(msg,color=Color(0xff9fc4a8));Text("Key 只保存在本机加密存储，不会进入源码。",color=Color.Gray)}}};item{Card{Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("通知与后台",style=MaterialTheme.typography.titleMedium);Text("提醒时间：07:30、07:35、12:30、15:30、17:45、20:00、22:30、23:00");Button(onClick={KeepAliveService.start(ctx)}){Text("开启常驻提醒")};Text("华为/荣耀：请在系统设置中允许自启动、后台活动，并锁定最近任务。",color=Color.Gray)}}};item{Card{Column(Modifier.padding(16.dp)){Text("数据",style=MaterialTheme.typography.titleMedium);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick={vm.exportJson(ctx)}){Text("导出 JSON")};OutlinedButton(onClick={picker.launch(arrayOf("application/json","text/plain"))}){Text("导入 JSON")}};Text("导出文件可在另一台设备导入，导入会追加记录。",color=Color.Gray)}}};item{Text("每日 AI 上限默认 15 次；API 失败时自动使用本地文案，卡片和数据照常工作。",color=Color.Gray)}}}
